import type { InventoryItem } from '@/types';

const GIST_ID = '7eaa69b6e8786827325f6be60a0b708e';
const GIST_FILENAME = 'lab-inventory.json';
const TOKEN_KEY = 'lab_inventory_token';

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}

export function setToken(token: string): void {
  localStorage.setItem(TOKEN_KEY, token);
}

export function clearToken(): void {
  localStorage.removeItem(TOKEN_KEY);
}

export async function pullFromGist(): Promise<InventoryItem[]> {
  const token = getToken();
  if (!token) return [];

  try {
    const resp = await fetch(`https://api.github.com/gists/${GIST_ID}`, {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/vnd.github+json',
      },
    });
    if (!resp.ok) return [];
    const data = await resp.json();
    const file = data.files?.[GIST_FILENAME];
    if (!file?.content) return [];
    return JSON.parse(file.content);
  } catch {
    return [];
  }
}

export async function pushToGist(items: InventoryItem[]): Promise<boolean> {
  const token = getToken();
  if (!token) return false;

  try {
    const resp = await fetch(`https://api.github.com/gists/${GIST_ID}`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/vnd.github+json',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        files: {
          [GIST_FILENAME]: {
            content: JSON.stringify(items, null, 2),
          },
        },
      }),
    });
    return resp.ok;
  } catch {
    return false;
  }
}