import { create } from 'zustand';
import type { Category, InventoryItem } from '@/types';
import { loadItems, saveItems } from '@/utils/storage';
import { pullFromGist, pushToGist, getToken, setToken, clearToken } from '@/utils/gist';

function generateId(): string {
  return crypto.randomUUID();
}

function mergeItems(local: InventoryItem[], remote: InventoryItem[]): InventoryItem[] {
  const map = new Map<string, InventoryItem>();
  for (const item of local) map.set(item.id, item);
  for (const item of remote) map.set(item.id, item);
  return Array.from(map.values());
}

interface InventoryState {
  items: InventoryItem[];
  activeCategory: Category;
  searchQuery: string;
  modalOpen: boolean;
  editingItem: InventoryItem | null;
  tokenConfigured: boolean;
  syncing: boolean;
  syncMessage: string;
  showTokenInput: boolean;

  load: () => Promise<void>;
  setActiveCategory: (cat: Category) => void;
  setSearchQuery: (q: string) => void;
  openAddModal: () => void;
  openEditModal: (item: InventoryItem) => void;
  closeModal: () => void;
  addItem: (data: Omit<InventoryItem, 'id'>) => void;
  updateItem: (data: InventoryItem) => void;
  deleteItem: (id: string) => void;
  syncFromGist: () => Promise<void>;
  saveToken: (token: string) => void;
  removeToken: () => void;
  setShowTokenInput: (show: boolean) => void;
}

export const useInventory = create<InventoryState>((set, get) => ({
  items: [],
  activeCategory: 'sers',
  searchQuery: '',
  modalOpen: false,
  editingItem: null,
  tokenConfigured: !!getToken(),
  syncing: false,
  syncMessage: '',
  showTokenInput: false,

  load: async () => {
    const local = loadItems();
    set({ items: local });

    if (getToken()) {
      set({ syncing: true, syncMessage: '正在同步云端数据...' });
      const remote = await pullFromGist();
      if (remote.length > 0) {
        const merged = mergeItems(local, remote);
        saveItems(merged);
        set({ items: merged, syncMessage: '同步完成' });
      } else {
        set({ syncMessage: local.length > 0 ? '已加载本地数据' : '数据为空' });
      }
      set({ syncing: false });
      setTimeout(() => set({ syncMessage: '' }), 2000);
    }
  },

  setActiveCategory: (cat) => set({ activeCategory: cat, searchQuery: '' }),

  setSearchQuery: (q) => set({ searchQuery: q }),

  openAddModal: () => set({ modalOpen: true, editingItem: null }),

  openEditModal: (item) => set({ modalOpen: true, editingItem: item }),

  closeModal: () => set({ modalOpen: false, editingItem: null }),

  addItem: (data) => {
    const newItem: InventoryItem = { ...data, id: generateId() };
    const items = [...get().items, newItem];
    saveItems(items);
    set({ items, modalOpen: false });
    pushToGist(items);
  },

  updateItem: (data) => {
    const items = get().items.map((it) => (it.id === data.id ? data : it));
    saveItems(items);
    set({ items, modalOpen: false, editingItem: null });
    pushToGist(items);
  },

  deleteItem: (id) => {
    const items = get().items.filter((it) => it.id !== id);
    saveItems(items);
    set({ items });
    pushToGist(items);
  },

  syncFromGist: async () => {
    set({ syncing: true, syncMessage: '正在同步...' });
    const remote = await pullFromGist();
    const local = loadItems();
    const merged = mergeItems(local, remote);
    saveItems(merged);
    set({ items: merged, syncing: false, syncMessage: '同步完成' });
    await pushToGist(merged);
    setTimeout(() => set({ syncMessage: '' }), 2000);
  },

  saveToken: (token) => {
    setToken(token);
    set({ tokenConfigured: true, showTokenInput: false });
    get().syncFromGist();
  },

  removeToken: () => {
    clearToken();
    set({ tokenConfigured: false });
  },

  setShowTokenInput: (show) => set({ showTokenInput: show }),
}));