import * as XLSX from 'xlsx';
import type { InventoryItem, Category } from '@/types';
import { CATEGORY_LABELS } from '@/types';

export function exportToExcel(items: InventoryItem[], category?: Category) {
  const filtered = category ? items.filter((it) => it.category === category) : items;

  const rows = filtered.map((item) => ({
    '分类': CATEGORY_LABELS[item.category],
    '名称': item.name,
    '购买时间': item.purchaseDate,
    '购买公司': item.company,
    '危化品': item.isHazardous ? '是' : '否',
    '保质期': item.expiryDate || '-',
    '购买量': item.totalAmount,
    '单位': item.unit,
    '余量': item.remainingAmount,
    '使用比例': item.totalAmount > 0
      ? `${((item.remainingAmount / item.totalAmount) * 100).toFixed(0)}%`
      : '0%',
    '状态': getStatus(item),
    '备注': item.remark || '',
  }));

  const ws = XLSX.utils.json_to_sheet(rows);

  const colWidths = [
    { wch: 12 },
    { wch: 24 },
    { wch: 12 },
    { wch: 20 },
    { wch: 8 },
    { wch: 12 },
    { wch: 8 },
    { wch: 6 },
    { wch: 8 },
    { wch: 10 },
    { wch: 8 },
    { wch: 30 },
  ];
  ws['!cols'] = colWidths;

  const wb = XLSX.utils.book_new();
  const sheetName = category ? CATEGORY_LABELS[category] : '全部';
  XLSX.utils.book_append_sheet(wb, ws, sheetName);

  const label = category ? CATEGORY_LABELS[category] : '全部';
  const dateStr = new Date().toISOString().slice(0, 10);
  const filename = `实验室库存_${label}_${dateStr}.xlsx`;

  XLSX.writeFile(wb, filename);
}

function getStatus(item: InventoryItem): string {
  const today = new Date().toISOString().slice(0, 10);
  if (item.expiryDate && item.expiryDate <= today) return '已过期';
  if (item.remainingAmount <= item.totalAmount * 0.2) return '低库存';
  return '正常';
}