import { Beaker, Cloud, CloudOff, Key, RefreshCw, LogOut } from 'lucide-react';
import { useInventory } from '@/hooks/useInventory';

export default function Header() {
  const tokenConfigured = useInventory((s) => s.tokenConfigured);
  const syncing = useInventory((s) => s.syncing);
  const syncMessage = useInventory((s) => s.syncMessage);
  const syncFromGist = useInventory((s) => s.syncFromGist);
  const removeToken = useInventory((s) => s.removeToken);
  const setShowTokenInput = useInventory((s) => s.setShowTokenInput);

  return (
    <header className="mb-8">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2.5 rounded-xl bg-gradient-to-br from-[#00e5ff]/20 to-[#00e5ff]/5 border border-[#00e5ff]/20">
            <Beaker className="w-7 h-7 text-[#00e5ff]" />
          </div>
          <div>
            <h1
              className="text-2xl font-bold tracking-wider bg-gradient-to-r from-[#00e5ff] to-[#00cee6] bg-clip-text text-transparent"
              style={{ fontFamily: "'Orbitron', sans-serif" }}
            >
              Lab Inventory
            </h1>
            <p className="text-xs text-[#4a5a6a] mt-0.5">课题组药品与耗材管理系统</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {syncMessage && (
            <span className="text-xs text-[#00e5ff] flex items-center gap-1.5">
              <RefreshCw className={`w-3 h-3 ${syncing ? 'animate-spin' : ''}`} />
              {syncMessage}
            </span>
          )}

          {tokenConfigured ? (
            <>
              <button
                onClick={syncFromGist}
                disabled={syncing}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs text-[#00e5ff] hover:bg-[#00e5ff]/10 border border-[#00e5ff]/20 transition-all disabled:opacity-50"
              >
                <RefreshCw className={`w-3.5 h-3.5 ${syncing ? 'animate-spin' : ''}`} />
                同步
              </button>
              <button
                onClick={removeToken}
                className="flex items-center gap-1 px-2 py-1.5 rounded-lg text-xs text-[#8899aa] hover:text-[#ff5252] hover:bg-[#ff5252]/10 transition-all"
                title="断开同步"
              >
                <LogOut className="w-3.5 h-3.5" />
              </button>
              <span className="flex items-center gap-1 text-xs text-[#00e676]">
                <Cloud className="w-3.5 h-3.5" />
                已同步
              </span>
            </>
          ) : (
            <button
              onClick={() => setShowTokenInput(true)}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs text-[#8899aa] hover:text-[#ffab00] hover:bg-[#ffab00]/10 border border-[#1a2d4a] hover:border-[#ffab00]/30 transition-all"
            >
              <Key className="w-3.5 h-3.5" />
              配置同步
            </button>
          )}
        </div>
      </div>
    </header>
  );
}